public final class Performer {
    public static final int MAX_SHOWS = 8;

    private final String name;
    private int shows;

    public Performer(String name) { this.name = name; }

    public static Performer sign(String name) { return new Performer(name); }

    public int getShows() { return shows; }

    public int book(int count) { return book(count, "Main Stage"); }
    public int book(int count, String stage) {
        shows += count;
        return shows;
    }
}

