class Performer(val name: String) {
    var shows: Int = 0
        private set

    @JvmOverloads
    fun book(count: Int, stage: String = "Main Stage"): Int {
        shows += count
        return shows
    }

    companion object {
        const val MAX_SHOWS = 8
        @JvmStatic fun sign(name: String) = Performer(name)
    }
}

