// lload_0: push the long param | ldc2_w: push 1000L | lrem: take 2 longs, push the remainder
// l2i: take a long, push an int   | ireturn: take the int and return it
static int cueNumber(long cueId) {
    return (int) (cueId % 1_000);
}

